// src/cache-aside.js
const express = require('express');
const redis = require('redis');

const app = express();
const client = redis.createClient({ url: 'redis://redis:6379' });

client.on('error', (err) => console.error('Redis error:', err));

// Simulate slow database query
const fetchFromDatabase = async (userId) => {
  console.log(`⏳ Fetching user ${userId} from database...`);
  await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate DB latency
  return {
    id: userId,
    name: `User ${userId}`,
    email: `user${userId}@example.com`,
    fetchedAt: new Date().toISOString(),
    source: 'database'
  };
};

// Cache-aside implementation
const getUserWithCache = async (userId) => {
  const cacheKey = `user:${userId}`;
  const TTL = 300; // 5 minutes

  try {
    // 1. Try to get from cache
    const cached = await client.get(cacheKey);

    if (cached) {
      console.log(`✅ Cache HIT for user ${userId}`);
      const data = JSON.parse(cached);
      data.source = 'cache';
      return data;
    }

    console.log(`❌ Cache MISS for user ${userId}`);

    // 2. If not in cache, fetch from database
    const userData = await fetchFromDatabase(userId);

    // 3. Store in cache for future requests
    await client.setEx(cacheKey, TTL, JSON.stringify(userData));

    return userData;
  } catch (error) {
    console.error('Cache error:', error);
    // Fallback to database on cache failure
    return await fetchFromDatabase(userId);
  }
};

app.get('/api/users/:id', async (req, res) => {
  const startTime = Date.now();
  const userData = await getUserWithCache(req.params.id);
  const duration = Date.now() - startTime;

  res.json({
    ...userData,
    responseTime: `${duration}ms`
  });
});

// Clear cache endpoint
app.delete('/api/cache/users/:id', async (req, res) => {
  await client.del(`user:${req.params.id}`);
  res.json({ message: 'Cache cleared', userId: req.params.id });
});

// Connect and start
(async () => {
  await client.connect();
  app.listen(3000, () => {
    console.log('🚀 Server running on http://localhost:3000');
    console.log('📊 Redis Commander: http://localhost:8081');
  });
})();

// src/write-through.js
const express = require('express');
const redis = require('redis');

const router = express.Router();
const client = redis.createClient({ url: 'redis://redis:6379' });

// Simulate database write
const writeToDatabase = async (userId, data) => {
  console.log(`💾 Writing user ${userId} to database...`);
  await new Promise(resolve => setTimeout(resolve, 500));
  return { ...data, savedAt: new Date().toISOString() };
};

// Write-through cache implementation
const updateUserWithCache = async (userId, updates) => {
  const cacheKey = `user:${userId}`;
  const TTL = 300;

  try {
    // 1. Write to database first
    const savedData = await writeToDatabase(userId, updates);

    // 2. Update cache immediately
    await client.setEx(cacheKey, TTL, JSON.stringify(savedData));
    console.log(`✅ Cache updated for user ${userId}`);

    return savedData;
  } catch (error) {
    console.error('Write-through error:', error);
    // If cache update fails, still return database result
    // Consider invalidating cache here
    await client.del(cacheKey);
    throw error;
  }
};

router.put('/users/:id', async (req, res) => {
  try {
    const userData = await updateUserWithCache(req.params.id, req.body);
    res.json({ success: true, data: userData });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

module.exports = { router, updateUserWithCache };

// src/cache-invalidation.js
const redis = require('redis');

class CacheManager {
  constructor(redisClient) {
    this.client = redisClient;
  }

  // Strategy 1: TTL-based expiration (automatic)
  async setWithTTL(key, value, ttlSeconds) {
    await this.client.setEx(key, ttlSeconds, JSON.stringify(value));
    console.log(`✅ Set ${key} with TTL: ${ttlSeconds}s`);
  }

  // Strategy 2: Pattern-based invalidation
  async invalidatePattern(pattern) {
    const keys = await this.client.keys(pattern);
    if (keys.length > 0) {
      await this.client.del(keys);
      console.log(`🗑️  Invalidated ${keys.length} keys matching: ${pattern}`);
    }
    return keys.length;
  }

  // Strategy 3: Tag-based invalidation
  async setWithTags(key, value, ttl, tags = []) {
    // Store the actual data
    await this.client.setEx(key, ttl, JSON.stringify(value));

    // Store tag references
    for (const tag of tags) {
      const tagKey = `tag:${tag}`;
      await this.client.sAdd(tagKey, key);
      await this.client.expire(tagKey, ttl);
    }

    console.log(`✅ Set ${key} with tags: ${tags.join(', ')}`);
  }

  async invalidateByTag(tag) {
    const tagKey = `tag:${tag}`;
    const keys = await this.client.sMembers(tagKey);

    if (keys.length > 0) {
      await this.client.del(keys);
      await this.client.del(tagKey);
      console.log(`🗑️  Invalidated ${keys.length} keys with tag: ${tag}`);
    }

    return keys.length;
  }

  // Strategy 4: Conditional invalidation based on version
  async setWithVersion(key, value, ttl, version) {
    const versionedKey = `${key}:v${version}`;
    await this.client.setEx(versionedKey, ttl, JSON.stringify({ ...value, version }));
    await this.client.set(`${key}:version`, version);

    // Clean up old versions
    const oldKeys = await this.client.keys(`${key}:v*`);
    for (const oldKey of oldKeys) {
      if (oldKey !== versionedKey) {
        await this.client.del(oldKey);
      }
    }
  }

  async getWithVersion(key) {
    const version = await this.client.get(`${key}:version`);
    if (!version) return null;

    const versionedKey = `${key}:v${version}`;
    const data = await this.client.get(versionedKey);
    return data ? JSON.parse(data) : null;
  }

  // Strategy 5: Cache warming
  async warmCache(keys, fetchFunction) {
    console.log(`🔥 Warming cache for ${keys.length} keys...`);

    const promises = keys.map(async (key) => {
      const data = await fetchFunction(key);
      await this.setWithTTL(key, data, 3600);
    });

    await Promise.all(promises);
    console.log(`✅ Cache warmed with ${keys.length} entries`);
  }

  // Get cache statistics
  async getStats() {
    const info = await this.client.info('stats');
    const keyspace = await this.client.info('keyspace');
    const memory = await this.client.info('memory');

    return {
      info,
      keyspace,
      memory,
      totalKeys: await this.client.dbSize()
    };
  }
}

// Usage example
const client = redis.createClient({ url: 'redis://redis:6379' });
await client.connect();

const cache = new CacheManager(client);

// Example: Tag-based invalidation
await cache.setWithTags('product:1', { name: 'Widget' }, 300, ['products', 'user:123']);
await cache.setWithTags('product:2', { name: 'Gadget' }, 300, ['products', 'user:123']);

// Invalidate all products for user 123
await cache.invalidateByTag('user:123');

module.exports = CacheManager;

// src/redis-structures.js
const redis = require('redis');

class AdvancedCache {
  constructor(redisClient) {
    this.client = redisClient;
  }

  // Use Redis Hash for object caching
  async cacheUserProfile(userId, profile) {
    const key = `user:${userId}:profile`;
    await this.client.hSet(key, profile);
    await this.client.expire(key, 3600);
    console.log(`✅ Cached profile for user ${userId}`);
  }

  async getUserProfile(userId) {
    const key = `user:${userId}:profile`;
    return await this.client.hGetAll(key);
  }

  // Use Redis List for recent items
  async addToRecentViews(userId, productId) {
    const key = `user:${userId}:recent`;
    await this.client.lPush(key, productId);
    await this.client.lTrim(key, 0, 9); // Keep only 10 items
    await this.client.expire(key, 86400); // 24 hours
  }

  async getRecentViews(userId, limit = 10) {
    const key = `user:${userId}:recent`;
    return await this.client.lRange(key, 0, limit - 1);
  }

  // Use Redis Set for unique items
  async addToFavorites(userId, productId) {
    const key = `user:${userId}:favorites`;
    await this.client.sAdd(key, productId);
    await this.client.expire(key, 86400);
  }

  async getFavorites(userId) {
    const key = `user:${userId}:favorites`;
    return await this.client.sMembers(key);
  }

  async isFavorite(userId, productId) {
    const key = `user:${userId}:favorites`;
    return await this.client.sIsMember(key, productId);
  }

  // Use Redis Sorted Set for leaderboards/rankings
  async updateScore(gameId, userId, score) {
    const key = `game:${gameId}:leaderboard`;
    await this.client.zAdd(key, { score, value: userId });
    await this.client.expire(key, 86400);
  }

  async getTopPlayers(gameId, count = 10) {
    const key = `game:${gameId}:leaderboard`;
    return await this.client.zRangeWithScores(key, 0, count - 1, { REV: true });
  }

  async getUserRank(gameId, userId) {
    const key = `game:${gameId}:leaderboard`;
    return await this.client.zRevRank(key, userId);
  }

  // Use Redis for distributed rate limiting
  async checkRateLimit(userId, maxRequests, windowSeconds) {
    const key = `ratelimit:${userId}`;
    const current = await this.client.incr(key);

    if (current === 1) {
      await this.client.expire(key, windowSeconds);
    }

    return {
      allowed: current <= maxRequests,
      current,
      limit: maxRequests,
      remaining: Math.max(0, maxRequests - current)
    };
  }

  // Use Redis for session storage
  async createSession(sessionId, userData, ttl = 3600) {
    const key = `session:${sessionId}`;
    await this.client.setEx(key, ttl, JSON.stringify(userData));
    return sessionId;
  }

  async getSession(sessionId) {
    const key = `session:${sessionId}`;
    const data = await this.client.get(key);
    return data ? JSON.parse(data) : null;
  }

  async extendSession(sessionId, additionalSeconds) {
    const key = `session:${sessionId}`;
    await this.client.expire(key, additionalSeconds);
  }
}

module.exports = AdvancedCache;

// src/cache-monitor.js
const redis = require('redis');

class CacheMonitor {
  constructor(redisClient) {
    this.client = redisClient;
    this.metrics = {
      hits: 0,
      misses: 0,
      errors: 0
    };
  }

  recordHit() {
    this.metrics.hits++;
  }

  recordMiss() {
    this.metrics.misses++;
  }

  recordError() {
    this.metrics.errors++;
  }

  getHitRate() {
    const total = this.metrics.hits + this.metrics.misses;
    return total === 0 ? 0 : (this.metrics.hits / total * 100).toFixed(2);
  }

  async getRedisInfo() {
    const info = await this.client.info();
    const stats = await this.client.info('stats');

    return {
      connectedClients: this.parseInfo(info, 'connected_clients'),
      usedMemory: this.parseInfo(info, 'used_memory_human'),
      totalKeys: await this.client.dbSize(),
      keyspaceHits: this.parseInfo(stats, 'keyspace_hits'),
      keyspaceMisses: this.parseInfo(stats, 'keyspace_misses'),
      evictedKeys: this.parseInfo(stats, 'evicted_keys')
    };
  }

  parseInfo(infoString, key) {
    const match = infoString.match(new RegExp(`${key}:([^\r\n]+)`));
    return match ? match[1] : 'N/A';
  }

  async getCacheReport() {
    const redisInfo = await this.getRedisInfo();
    const appHitRate = this.getHitRate();

    const redisHits = parseInt(redisInfo.keyspaceHits) || 0;
    const redisMisses = parseInt(redisInfo.keyspaceMisses) || 0;
    const redisTotal = redisHits + redisMisses;
    const redisHitRate = redisTotal === 0 ? 0 : (redisHits / redisTotal * 100).toFixed(2);

    return {
      timestamp: new Date().toISOString(),
      application: {
        hits: this.metrics.hits,
        misses: this.metrics.misses,
        errors: this.metrics.errors,
        hitRate: `${appHitRate}%`
      },
      redis: {
        ...redisInfo,
        hitRate: `${redisHitRate}%`
      },
      recommendations: this.generateRecommendations(redisHitRate, redisInfo)
    };
  }

  generateRecommendations(hitRate, info) {
    const recommendations = [];

    if (parseFloat(hitRate) < 80) {
      recommendations.push('Cache hit rate is below 80%. Consider increasing TTLs or cache warming.');
    }

    const evicted = parseInt(info.evictedKeys) || 0;
    if (evicted > 1000) {
      recommendations.push('High eviction count. Consider increasing maxmemory.');
    }

    return recommendations;
  }

  // Express middleware for automatic monitoring
  middleware() {
    return async (req, res, next) => {
      const originalJson = res.json;

      res.json = function(data) {
        if (data && data.source === 'cache') {
          this.recordHit();
        } else if (data && data.source === 'database') {
          this.recordMiss();
        }
        return originalJson.call(res, data);
      }.bind(this);

      next();
    };
  }
}

